package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;
public final class PlayerModelEditor{
 private static final String[] KEYS={"arm_length","shoulder_width","neck_length","chest","neck_size","shoulder_height","leg_length","thigh_size","waist_size","arm_size","calf_size"};
 private static final String[] LABELS={"Arm Length","Shoulder Width","Neck Length","Chest Measurement","Neck Size","Shoulder Height","Leg Length","Thigh Size","Waist Size","Arm Size","Calf Size"};
 private static int dp(Activity a,int n){return Math.round(n*a.getResources().getDisplayMetrics().density);}
 private static String manage(Activity a,String action,JSONObject req)throws Exception{return(String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,action,req.toString());}
 private static void error(Activity a,Exception e){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("Player Model").setMessage(String.valueOf(e.getCause()==null?e.getMessage():e.getCause().getMessage())).setPositiveButton("Close",null).show();}
 public static void attach(Activity a,LinearLayout panel,JSONObject player){Button b=new Button(a);b.setText("Player Model · Body Proportions");b.setAllCaps(false);b.setMinHeight(dp(a,48));b.setOnClickListener(v->{b.setEnabled(false);new Thread(()->{try{JSONObject data=new JSONObject(manage(a,"ui75_model_get",player));a.runOnUiThread(()->{b.setEnabled(true);if(!a.isFinishing())form(a,player,data);});}catch(Exception e){a.runOnUiThread(()->{b.setEnabled(true);error(a,e);});}},"PlayerModelLoad").start();});panel.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 private static void form(Activity a,JSONObject player,JSONObject data){JSONObject values=data.optJSONObject("values"),base=data.optJSONObject("baseline");ScrollView scroll=new ScrollView(a);LinearLayout col=new LinearLayout(a);col.setOrientation(1);col.setPadding(dp(a,16),dp(a,12),dp(a,16),dp(a,12));col.setBackgroundColor(0xff101f38);scroll.addView(col);TextView note=new TextView(a);note.setText("0–14 body proportions. Original keeps the game's current value. Enable a field to change it; 7 is neutral. Save before entering the game.");note.setTextColor(0xffdcecf7);col.addView(note);CheckBox[] enabled=new CheckBox[11];SeekBar[] bars=new SeekBar[11];
  for(int i=0;i<11;i++){final int k=i;boolean custom=values!=null&&values.has(KEYS[i]);final String original=base!=null&&base.has(KEYS[i])?(base.optInt(KEYS[i])==15?"7 (native default)":String.valueOf(base.optInt(KEYS[i]))):"unavailable";int value=custom?values.optInt(KEYS[i],7):base==null?7:(base.optInt(KEYS[i],7)==15?7:base.optInt(KEYS[i],7));CheckBox toggle=new CheckBox(a);toggle.setTextColor(0xffedf8ff);toggle.setMinHeight(dp(a,48));toggle.setChecked(custom);toggle.setText(LABELS[i]+(custom?" · "+value:" · Original: "+original));col.addView(toggle);SeekBar bar=new SeekBar(a);bar.setMax(14);bar.setProgress(value);bar.setEnabled(custom);col.addView(bar,new LinearLayout.LayoutParams(-1,dp(a,48)));enabled[i]=toggle;bars[i]=bar;toggle.setOnCheckedChangeListener((button,on)->{bar.setEnabled(on);toggle.setText(LABELS[k]+(on?" · "+bar.getProgress():" · Original: "+original));});bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(toggle.isChecked())toggle.setText(LABELS[k]+" · "+p);}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});}
  AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Player Model").setView(scroll).setNegativeButton("Cancel",null).setNeutralButton("Restore Original",null).setPositiveButton("Save",null).create();dialog.show();ResponsiveUi.fit(a,dialog);dialog.getButton(-3).setOnClickListener(v->{for(CheckBox box:enabled)box.setChecked(false);});dialog.getButton(-1).setOnClickListener(v->{try{JSONObject req=new JSONObject(player.toString()),selected=new JSONObject();for(int i=0;i<11;i++)if(enabled[i].isChecked())selected.put(KEYS[i],bars[i].getProgress());req.put("values",selected);dialog.getButton(-1).setEnabled(false);dialog.getButton(-3).setEnabled(false);new Thread(()->{try{manage(a,"ui75_model_apply",req);a.runOnUiThread(()->{dialog.dismiss();Toast.makeText(a,"Player model saved",Toast.LENGTH_SHORT).show();});}catch(Exception e){a.runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);dialog.getButton(-3).setEnabled(true);error(a,e);});}},"PlayerModelSave").start();}catch(Exception e){error(a,e);}});
 }
}
